export async function toggleFlag(
  actor: Actor,
  input: ToggleFeatureFlagInput,
): Promise<Organization> {
  assertCan(actor, "org:manage_flags", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const definition = getFlagDefinition(input.flag);
  if (!definition.overridable) {
    throw new Error(`Feature "${input.flag}" cannot be overridden per org`);
  }

  const current = new Set(org.settings.enabledFlagOverrides);
  if (input.enabled) {
    current.add(input.flag);
  } else {
    current.delete(input.flag);
  }

  const updated = await orgRepo.updateOrg(input.orgId, {
    orgId: input.orgId,
    settings: { enabledFlagOverrides: [...current] },
  });

  await emit("flag.toggled", {
    ...actorEnvelope(actor),
    flag: input.flag,
    enabled: isEnabled(input.flag, buildFlagContext(actor, updated)),
  });

  return updated;
}

/** `2026-06-01T0{hour}:00:00.000Z` — every test gets its own hour so a scan
 * driven by one test's `now` never also matches another test's org. */
function nowAtHour(hour: number): Date {
  return new Date(Date.UTC(2026, 5, 1, hour, 0, 0, 0));
}

/** Creates a tenant on `plan` whose digest fires only at `digestHourUtc`, and
 * registers it with the usage rollup so `listOrgIdsForRollup` finds it. */
async function makeTenant(
  slug: string,
  digestHourUtc: number,
  plan: PlanId = "growth",
): Promise<Tenant> {
  const tenant = await createTenant(slug, plan);
  await orgRepo.updateOrg(tenant.org.id, {
    orgId: tenant.org.id,
    settings: { digestHourUtc },
  });
  await usageRepo.recomputeUsage(tenant.org.id);
  return tenant;
}

/** Subscribes a member to the digest by setting one `digestOnly` preference. */
async function subscribeToDigest(tenant: Tenant): Promise<void> {
  await preferenceRepo.upsertPreference({
    orgId: tenant.org.id,
    userId: tenant.userIds.member,
    kind: "comment_created",
    inApp: false,
    email: false,
    digestOnly: true,
  });
}

