cat > tests/services/tmp-org-settings.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import * as orgRepo from "@/server/repositories/organization-repository";
import { updateOrganization } from "@/server/services/organization-service";
import { updateOrganizationSchema } from "@/schemas/organization";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("settings patch", () => {
  it("only changes submitted keys", async () => {
    const a = await createTenant("aa", "starter");
    const b = await createTenant("bb", "starter");
    await orgRepo.updateOrg(a.org.id, { orgId: a.org.id, settings: { digestHourUtc: 18, requireTwoFactor: true, enabledFlagOverrides: ["digest", "activity-feed"] } });
    const admin = a.actors.admin;
    const parse = (x: unknown) => updateOrganizationSchema.parse(x);
    let o = await updateOrganization(admin, parse({ orgId: a.org.id, settings: { defaultIssueStatus: "todo" } }));
    expect(o.settings).toMatchObject({ defaultIssueStatus: "todo", digestHourUtc: 18, requireTwoFactor: true, enabledFlagOverrides: ["digest", "activity-feed"] });
    o = await updateOrganization(admin, parse({ orgId: a.org.id, settings: { allowPublicProjects: true } }));
    expect(o.settings).toMatchObject({ allowPublicProjects: true, digestHourUtc: 18, requireTwoFactor: true });
    o = await updateOrganization(admin, parse({ orgId: a.org.id, name: "Renamed" }));
    expect(o.name).toBe("Renamed");
    expect(o.settings).toMatchObject({ allowPublicProjects: true, digestHourUtc: 18, requireTwoFactor: true, enabledFlagOverrides: ["digest", "activity-feed"] });
    o = await updateOrganization(admin, parse({ orgId: a.org.id, settings: { digestHourUtc: 0, requireTwoFactor: false, enabledFlagOverrides: [] } }));
    expect(o.settings).toMatchObject({ digestHourUtc: 0, requireTwoFactor: false, enabledFlagOverrides: [] });
    const bb = await orgRepo.findOrgById(b.org.id);
    expect(bb!.settings.digestHourUtc).toBe(7);
  });
});
EOF
npx vitest run tests/services/tmp-org-settings.test.ts 2>&1 | tail -20; rm tests/services/tmp-org-settings.test.ts

